import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/pipeline');
await p.waitForTimeout(1000);
const names = () => p.$$eval('#pl .nm', n=>n.map(x=>x.textContent));
async function drag(from, to){ // to: name of item to drop before
  const items = await p.$$('#pl li');
  let src=null, dst=null;
  for (const li of items){ const t=await li.textContent(); if(t.includes(from)) src=li; }
  const h = await src.$('.h'); const hb = await h.boundingBox();
  await p.mouse.move(hb.x+hb.width/2, hb.y+hb.height/2);
  await p.mouse.down();
  let target = null;
  for (const li of await p.$$('#pl li')){ if((await li.textContent()).includes(to)) target=li; }
  const tb = await target.boundingBox();
  const y = to==='END' ? tb.y+tb.height-2 : tb.y+2;
  await p.mouse.move(hb.x+hb.width/2, y, {steps:20});
  await p.mouse.up();
}
await drag('Invoicing','Shipping');
console.log(await names());
await drag('Packing','Credit check');
console.log(await names());
await p.click('#save');
await p.waitForTimeout(800);
console.log(await p.textContent('#done'));
await p.reload(); await p.waitForTimeout(1000);
console.log(await names());
await b.close();
EOF
